-- The USL is active: these read only semantic-layer tables, never the raw sources.
SHOW TABLES IN lightning.metastore.rrcc.trialmatch;
SELECT d.histology, d.stage_group, COUNT(*) AS patients FROM lightning.metastore.rrcc.trialmatch.diagnosis d GROUP BY d.histology, d.stage_group ORDER BY patients DESC;
SELECT b.gene, b.alteration, COUNT(DISTINCT b.patient_id) AS patients FROM lightning.metastore.rrcc.trialmatch.biomarker b WHERE b.status = 'detected' GROUP BY b.gene, b.alteration ORDER BY patients DESC;
SELECT p.patient_id, p.given_name, p.family_name, b.gene, b.alteration, x.therapy_class, x.line_of_therapy
FROM lightning.metastore.rrcc.trialmatch.patient p
JOIN lightning.metastore.rrcc.trialmatch.biomarker b ON b.patient_id = p.patient_id AND b.status = 'detected'
JOIN lightning.metastore.rrcc.trialmatch.therapy x ON x.patient_id = p.patient_id
WHERE b.gene = 'EGFR' ORDER BY p.patient_id LIMIT 10;

